func decodePGNCandidates(info MessageInfo, payload []uint8, candidates ...PGN) (PGN, error) {
	var errs []error
	for _, candidate := range candidates {
		candidate.SetMessageInfo(info)
		if err := candidate.DecodePayload(payload); err != nil {
			errs = append(errs, err)
			continue
		}
		return candidate, nil
	}
	if len(errs) == 0 {
		return nil, fmt.Errorf("no PGN struct for %d", info.PGN)
	}
	return nil, fmt.Errorf("no matching PGN struct for %d: %w", info.PGN, errors.Join(errs...))
}
